text(await tools.exec_command({cmd:"node --import tsx --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { buildCodexPrompt, CODEX_MODEL, CODEX_REASONING_EFFORT } from './src/agents/codex.ts';
import { buildClaudePrompt, CLAUDE_MODEL, CLAUDE_EFFORT } from './src/agents/claude.ts';
import { assertWorkerContext, MAX_WORKER_CONTEXT_LENGTH, MAX_WORKER_PROMPT_LENGTH } from './src/agents/context.ts';
const executeFile = promisify(execFile);
const parent = '/tmp/jev-live-repair-p1v88umg';
const manifest = JSON.parse(await readFile(`${parent}/manifest.json`, 'utf8'));
const summary = {};
for (const agent of ['codex', 'claude']) {
  const root = manifest[agent].root;
  const traceNames = (await readdir(`${root}/traces`)).filter(name => name.endsWith('.jsonl'));
  assert.equal(traceNames.length, 1);
  const trace = `${root}/traces/${traceNames[0]}`;
  const records = (await readFile(trace, 'utf8')).trim().split('\n').map(line => JSON.parse(line));
  assert.equal(records.length, 7);
  const workerAction = `CALL_${agent.toUpperCase()}`;
  assert.deepEqual(records.map(record => record.proposal.selected.action), ['SEARCH_REPO', 'READ_FILE', 'RUN_TESTS', 'ASK_USER', workerAction, 'RUN_TESTS', 'FINISH']);
  assert.ok(records.every(record => record.approval.kind === 'approve'));
  const failed = records[2];
  const repair = records[4];
  const passed = records[5];
  const final = records[6];
  const approved = JSON.parse(await readFile(`${parent}/${agent}-approved-request.json`, 'utf8'));
  assert.deepEqual(repair.toolInput, approved, 'Execution trace input differs from reviewed approval display.');
  const context = approved.context;
  assertWorkerContext(context);
  assert.equal(context.validationGeneration, 0);
  assert.equal(context.validation.script, 'test');
  assert.equal(context.validation.exitCode, 1);
  assert.equal(context.validation.passed, false);
  assert.ok(context.validation.summary.includes('-1 !== 5'));
  assert.equal(context.clarifications[0].iteration, 4);
  assert.ok(context.clarifications[0].text.includes('positive, negative, and fractional inputs'));
  assert.deepEqual(new Set(context.findings.map(finding => finding.source)), new Set(['search', 'read']));
  const contextCharacters = JSON.stringify(context).length;
  const prompt = agent === 'codex' ? buildCodexPrompt(approved.task, context) : buildClaudePrompt(approved.task, context);
  assert.ok(contextCharacters <= MAX_WORKER_CONTEXT_LENGTH);
  assert.ok(prompt.length <= MAX_WORKER_PROMPT_LENGTH);
  assert.equal(failed.toolResult.exitCode, 1);
  assert.equal(failed.stateAfter.tests.passed, false);
  assert.deepEqual(repair.approval.history.map(item => item.kind), ['alternative', 'approve']);
  assert.equal(repair.approval.history[0].action, workerAction);
  assert.equal(repair.workerRequest.retryReason, 'Repair after failed independent validation.');
  assert.equal(repair.toolResult.ok, true);
  assert.equal(repair.toolResult.exitCode, 0);
  assert.equal(repair.toolResult.timedOut, false);
  assert.deepEqual(repair.stateAfter.tests, { ran: false });
  assert.equal(repair.stateAfter.evidence.validationGeneration, 1);
  assert.deepEqual(repair.stateAfter.filesModified, ['src/add.js']);
  assert.deepEqual(repair.stateAfter.repo.gitStatus, [' M src/add.js']);
  assert.equal(passed.toolResult.exitCode, 0);
  assert.equal(passed.stateAfter.tests.passed, true);
  assert.equal(passed.stateAfter.evidence.validation.generation, 1);
  assert.ok(passed.stateAfter.tests.summary.includes('pass 3'));
  assert.equal(final.policy.selected, 'FINISH');
  assert.equal(final.stateAfter.currentGoal, 'Task complete.');
  assert.equal(final.stateAfter[`${agent}Calls`], 1);
  const other = agent === 'codex' ? 'claude' : 'codex';
  assert.equal(final.stateAfter[`${other}Calls`], 0);
  assert.deepEqual(final.stateAfter.filesModified, ['src/add.js']);
  const changed = [];
  for (const [name, digest] of Object.entries(manifest[agent].sha256)) {
    if (createHash('sha256').update(await readFile(`${root}/${name}`)).digest('hex') !== digest) changed.push(name);
  }
  assert.deepEqual(changed, ['src/add.js']);
  const gitStatus = (await executeFile('git', ['--no-optional-locks', 'status', '--porcelain=v1', '--untracked-files=all'], { cwd: root })).stdout.replace(/\r?\n$/u, '');
  assert.equal(gitStatus, ' M src/add.js');
  assert.equal((await executeFile('git', ['remote'], { cwd: root })).stdout.trim(), '');
  const version = (await executeFile(agent, ['--version'])).stdout.trim();
  summary[agent] = {
    root, trace, cliVersion: version, model: agent === 'codex' ? CODEX_MODEL : CLAUDE_MODEL,
    effort: agent === 'codex' ? CODEX_REASONING_EFFORT : CLAUDE_EFFORT,
    status: 'finished', iterations: 7, workerCalls: 1,
    workerExitCode: 0, workerDurationMs: repair.toolResult.durationMs, timedOut: false,
    validationBefore: { exitCode: 1, generation: 0, testsPassed: 0, testsFailed: 3 },
    validationAfter: { exitCode: 0, generation: 1, testsPassed: 3, testsFailed: 0 },
    changedFiles: changed, recordedModifiedFiles: final.stateAfter.filesModified,
    protectedFileHashesUnchanged: true, approvalDisplayMatchesExecutionTrace: true,
    contextCharacters, promptCharacters: prompt.length,
    contextIncludes: ['real validation failure', 'user clarification', 'search/read provenance'],
  };
}
await writeFile(`${parent}/verification-summary.json`, JSON.stringify(summary, null, 2) + '\n');
console.log(JSON.stringify(summary, null, 2));
NODE","max_output_tokens":3200}));

