  tools.exec_command({cmd:"entire api --to cell '/api/v1/repos/{repo_id}/trails/19'",max_output_tokens:12000}),
  tools.write_stdin({session_id:92698,chars:"\u0003",yield_time_ms:1000,max_output_tokens:1500}),
  tools.clock__curr_time({})
]);
for (let i=0;i<results.length;i++) {
  const r=results[i];
  if (i===0 && r.status==="fulfilled" && r.value.exit_code===0) {
    const data=JSON.parse(r.value.output);
    text({runner:data.runners.find(x=>x.runner_id==="trail-review"),gates:data.mergeability.gates.map(x=>({key:x.gate_key,state:x.state,status:x.status,updated:x.created_at,value:x.value,rationale:x.rationale}))});
  } else text({i,...r});
}

