  tools.exec_command({cmd:"git fetch origin",max_output_tokens:2000})
]);
for(let i=0;i<results.length;i++) text({i,...results[i]});

text(await tools.exec_command({cmd:"entire status --json",max_output_tokens:2000}));
text(await tools.exec_command({cmd:"entire search 'PLAN next milestone worker context repair' --json --compact --limit 5",max_output_tokens:7000}));
